grep -E "TOTAL ENERGY|GEOMETRY OPTIMIZATION" opt1.log | tail -3
cat > check.py << 'EOF'
import numpy as np, sys
from scipy.spatial.distance import cdist
L=open(sys.argv[1]).read().split("\n")[2:]
S=[];X=[]
for l in L:
    p=l.split()
    if len(p)==4: S.append(p[0]); X.append([float(x) for x in p[1:]])
X=np.array(X); S=np.array(S)
rh=np.where(S=='Rh')[0][0]
D=cdist(X[[rh]],X)[0]
for i in np.argsort(D)[:10]: print(S[i], i, round(D[i],3))
# connectivity check
Dm=cdist(X,X)
for i in range(len(S)):
    if S[i]=='Rh': continue
    nb=[j for j in range(len(S)) if j!=i and S[j]!='Rh' and Dm[i,j]<(1.3 if (S[i]=='H' or S[j]=='H') else 1.75)]
    exp={'C':None,'H':1,'F':1,'O':2,'N':None}
    if S[i]=='H' and len(nb)!=1: print("bad H",i,nb)
    if S[i]=='F' and len(nb)!=1: print("bad F",i,nb)
    if S[i]=='O' and len(nb)!=2: print("bad O",i,nb)
    if S[i]=='C' and len(nb) not in (3,4): print("C",i,len(nb))
EOF
python check.py opt1.xyz
